let data=null;
let direction='outbound';
let routeId='local';
const routes={local:{label:'吉安 → 瑞穗',from:'吉安',to:'瑞穗',weather:['吉安鄉','瑞穗鄉','花蓮市']},'hualien-taipei':{label:'花蓮 → 臺北',from:'花蓮',to:'臺北',weather:['花蓮市']},'hualien-luodong':{label:'花蓮 → 羅東',from:'花蓮',to:'羅東',weather:['花蓮市']}};
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stationName=s=>String(s??'').replace(/^\d+-/,'');
const taipei=d=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const stamp=t=>t?new Date(t).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false}):'尚無資料';
const age=t=>t?(Date.now()-Date.parse(t))/60000:Infinity;
const statusText=t=>t?.status?`官方動態：${t.status}`:t?.statusCheckedAt?'官方已查詢：未回報異常':'尚未取得官方動態';
const statusTone=t=>t?.status?/誤點|停駛|取消/.test(t.status)?'bad':'good':t?.statusCheckedAt?'checked':'unknown';
const parseMinutes=s=>{const m=String(s||'').match(/(\d{2}):(\d{2})/);return m?Number(m[1])*60+Number(m[2]):9999};

function active(){const date=$('date').value,source=data?.days?.[date],profile=routes[routeId];let route=source?.routes?.find(r=>r.id===routeId&&r.direction===direction);let rows=route?.trains||[];if(routeId==='local')rows=source?.trains?.filter(t=>t.direction===direction)||[];return {date,source,profile,route,rows};}
function setRouteByInputs(){const from=$('from').value.trim().replace('台北','臺北'),to=$('to').value.trim().replace('台北','臺北');const match=Object.entries(routes).find(([,r])=>r.from===from&&r.to===to);if(match)routeId=match[0];else routeId='custom';}
function routeButtons(){const box=$('saved-routes');box.innerHTML=Object.entries(routes).map(([id,r])=>`<button type="button" data-route="${id}">${r.from} → ${r.to}</button>`).join('');for(const b of box.querySelectorAll('button'))b.onclick=()=>{routeId=b.dataset.route;$('from').value=routes[routeId].from;$('to').value=routes[routeId].to;render()};}
function statusMarkup(t,stale=false){const text=stale?'動態資料已過期':statusText(t);return `<div class="status-line ${statusTone(t)}"><strong>${esc(text)}</strong>${t?.statusCheckedAt?`<small>動態取回 ${esc(stamp(t.statusCheckedAt))}</small>`:''}</div>`;}
function trainUrl(no,date){return `https://www.railway.gov.tw/tra-tip-web/tip/tip001/tip112/querybytrainno?rideDate=${date.replaceAll('-','/')}&trainNo=${encodeURIComponent(no)}`;}
function render(){if(!data)return;const {date,source,profile,route,rows}=active();const stale=age(route?.checkedAt||source?.checkedAt)>15;const custom=routeId==='custom';
  $('from').value=custom?$('from').value:profile.from;$('to').value=custom?$('to').value:profile.to;$('journey-title').textContent=custom?`${$('from').value||'起點'} → ${$('to').value||'終點'}`:profile.label;
  $('freshness').textContent=source?`列車資料取回：${stamp(route?.checkedAt||source.checkedAt)}${stale?' ｜已過期，請以台鐵公告為準。':' ｜班次與官方動態已自動查詢。'}`:'這個日期尚未取得資料，請換日期或等待下一輪自動更新。';
  $('rail-status').textContent=(data.rail?.text||'尚未取得路線公告')+' · '+stamp(data.rail?.checkedAt);
  $('mode-note').textContent=custom?'這個路線尚未建立自動擷取設定；先保留輸入，下一步可加入常用路線。':'列車位置以官方動態為準；沒有回報時不以動畫猜測位置。';
  const next=rows[0];
  $('next-train').innerHTML=next?`<div class="next-time">${esc(next.departure)}</div><div class="next-name">${esc(next.type)} <b>${esc(next.no)}</b></div>${statusMarkup(next,stale)}<p>${esc(stationName(next.from))} 出發 → ${esc(stationName(next.to))} 抵達 ${esc(next.arrival)}</p><a href="${trainUrl(next.no,date)}" target="_blank" rel="noopener">查看官方逐站動態 ↗</a>`:'<div class="no-data">這個日期尚未有可用班次。<br><small>路線資料會由下一輪官方查詢補上。</small></div>';
  $('hero-train').innerHTML=next?`<div class="hero-line"><span class="hero-type">${esc(next.type)} ${esc(next.no)}</span><span class="hero-status">${esc(next.status||'行程已建立')}</span></div><div class="hero-times"><strong>${esc(next.departure)}</strong><span class="hero-arrow">→</span><strong>${esc(next.arrival)}</strong></div><div class="hero-caption"><span>${esc(stationName(next.from))}</span><span>${esc(stationName(next.to))}</span></div>`:'<div class="no-data">尚無這條路線的本日資料。</div>';
  $('timeline').innerHTML=next?`<div class="timeline-track"><div class="station-node active"><i></i><b>${esc(stationName(next.from))}</b><span>${esc(next.departure)} 出發</span></div><div class="moving-train" aria-label="列車 ${esc(next.no)}">▰</div><div class="station-node"><i></i><b>${esc(stationName(next.to))}</b><span>${esc(next.arrival)} 抵達</span></div></div><p class="timeline-note">${next.status?'位置狀態：官方動態已回報':'位置狀態：依官方時刻預估'} · 不以動畫取代實際回報</p>`:'<div class="timeline-empty">選擇其他日期，查看完整行程。</div>';
  $('trains').innerHTML=rows.length?rows.map(t=>`<article class="train-card"><div class="train-card-top"><span>${esc(t.type)}</span><b>${esc(t.no)}</b><em>${direction==='outbound'?'去程':'回程'}</em></div><div class="train-card-time"><strong>${esc(t.departure)}</strong><span>→</span><strong>${esc(t.arrival)}</strong></div><div class="train-card-stations"><span>${esc(stationName(t.from))}</span><span>${esc(stationName(t.to))}</span></div>${statusMarkup(t,stale)}<a href="${trainUrl(t.no,date)}" target="_blank" rel="noopener">逐站動態 ↗</a></article>`).join(''):'<div class="empty">目前沒有符合的班次。請確認日期、起訖站，或等待自動擷取。</div>';
  const weatherNames=profile?.weather||['花蓮市'];$('weather').innerHTML=weatherNames.map((name,i)=>{const w=data.weather?.[name],hours=w?.hours?.filter(h=>h.date===date)||[],h=hours[0];return `<article class="weather-stop ${i===0?'visible':''}"><div class="weather-stop-index">0${i+1}</div><div><b>${esc(name)}</b><small>${w?'預報取回 '+stamp(w.checkedAt):'沿線預報下一輪擷取'}</small></div><div class="weather-main">${h?`<strong>${esc(h.temperature)}°</strong><span>${esc(h.description||'天氣狀況未提供')}<br>雨 ${esc(h.rain||'未提供')} · 風 ${esc(h.wind||'未提供')}</span>`:'<span>目前尚無此段預報</span>'}</div></article>`}).join('');
  $('collection-info').textContent=`共 ${rows.length} 班 · ${stale?'動態已過期':'官方資料已取回 '+stamp(route?.checkedAt||source?.checkedAt)}`;
}
async function refresh(){try{const r=await fetch(`data.json?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw Error();data=await r.json();if(!$('date').dataset.chosen){const now=new Date(),today=taipei(now),tomorrow=taipei(new Date(+now+86400000));const h=Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',hour:'2-digit',hour12:false}).format(now));$('date').value=h>=20&&data.days?.[tomorrow]?tomorrow:data.days?.[today]?today:tomorrow;direction=h>=12&&h<20?'inbound':'outbound';}render()}catch{$('freshness').textContent='資料讀取失敗，請稍後再試。'}}
routeButtons();$('date').value=taipei(new Date());$('trip-form').onsubmit=e=>{e.preventDefault();setRouteByInputs();$('date').dataset.chosen='true';render()};$('swap').onclick=()=>{const a=$('from').value;$('from').value=$('to').value;$('to').value=a;setRouteByInputs();render()};for(const id of ['outbound','inbound'])$(id).onclick=()=>{direction=id;for(const x of ['outbound','inbound'])$(x).setAttribute('aria-pressed',String(x===id));render()};$('date').onchange=()=>{$('date').dataset.chosen='true';render()};setInterval(()=>{$('clock').textContent=stamp(new Date().toISOString())},1000);setInterval(()=>{if(!document.hidden)refresh()},60000);refresh();
